import{B as e,Q as t,s as n,z as r}from"./chunks/framework.nczTtCLp.js";import"./chunks/booker-show-detail-qr-code-share.kghpGyku.js";var i=JSON.parse(`{"title":"Book Your First Show","description":"","frontmatter":{},"headers":[],"relativePath":"guide/book-your-first-show.md","filePath":"guide/book-your-first-show.md"}`),a={name:`guide/book-your-first-show.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="book-your-first-show" tabindex="-1">Book Your First Show <a class="header-anchor" href="#book-your-first-show" aria-label="Permalink to &quot;Book Your First Show&quot;">​</a></h1><p>A first-time booker&#39;s walkthrough: from an empty calendar to a completed show with results. Written for anyone holding the BOOKER role (admins can do all of this too).</p><p><strong>Before you start:</strong> your admin must have set up the promotion — wrestlers on the roster, at least one arena, and (for AI narration) a working AI provider. See <a href="./admin-getting-started.html">Admin Getting Started</a> if anything is missing.</p><hr><h2 id="step-1-—-create-the-show" tabindex="-1">Step 1 — Create the show <a class="header-anchor" href="#step-1-—-create-the-show" aria-label="Permalink to &quot;Step 1 — Create the show&quot;">​</a></h2><p>Open <strong>Show List</strong> from the navigation and create a new show. You&#39;ll pick:</p><ul><li><strong>Show type</strong> — the kind of event (weekly TV, premium live event, house show). The type shapes expectations: weekly shows build momentum, premium events are where titles change.</li><li><strong>Date</strong> — when the show runs on the calendar.</li><li><strong>Arena</strong> — where. Capacity feeds attendance and fan calculations.</li></ul><p><img src="/atw-rpg/docs/screenshots/booker-show-planning.png" alt="Show planning"></p><hr><h2 id="step-2-—-fill-the-card" tabindex="-1">Step 2 — Fill the card <a class="header-anchor" href="#step-2-—-fill-the-card" aria-label="Permalink to &quot;Step 2 — Fill the card&quot;">​</a></h2><p>A show is an ordered list of <strong>segments</strong>. Add segments one by one; each has a type, participants, and (for matches) a match type:</p><ul><li><strong>Matches</strong> are the heart of the card: pick two or more wrestlers and a match type (singles, tag, triple threat… — the list comes from your enabled expansions). The winner is decided when the show runs.</li><li><strong>Promos</strong> give wrestlers mic time to build heat without a physical contest — use them between matches to pace the show.</li><li><strong>Championship matches</strong>: attach a title to a match to put it on the line. Champions who retain gain fans; losers lose them.</li></ul><p>Watch the <strong>proposed card</strong> helpers as you build — the game flags problems before showtime (a wrestler booked twice, a stipulation that doesn&#39;t match the participants, a card with no main event).</p><p><img src="/atw-rpg/docs/screenshots/booker-show-planning-proposed-card.png" alt="Proposed card"></p><hr><h2 id="step-3-—-designate-the-main-event" tabindex="-1">Step 3 — Designate the main event <a class="header-anchor" href="#step-3-—-designate-the-main-event" aria-label="Permalink to &quot;Step 3 — Designate the main event&quot;">​</a></h2><p>The last non-promo segment on the card is the night&#39;s headline. Main-event winners earn <strong>elevated fan gains</strong> and the AI narration treats the segment as the climax — so put your hottest rivalry there.</p><hr><h2 id="step-4-—-run-the-show" tabindex="-1">Step 4 — Run the show <a class="header-anchor" href="#step-4-—-run-the-show" aria-label="Permalink to &quot;Step 4 — Run the show&quot;">​</a></h2><p>When the card is final, run the show. The game adjudicates each segment in order:</p><ul><li>Match outcomes roll from wrestler stats, health, stamina, and momentum — the better-prepared wrestler usually wins, but upsets happen.</li><li>With an AI provider configured, every segment gets live narration and commentary you can share with your community (shows expose a QR code link for viewers).</li><li>Fans, rankings, and injuries update as segments complete.</li></ul><p><img src="/atw-rpg/docs/screenshots/booker-show-detail-qr-code-share.png" alt="Show QR share"></p><hr><h2 id="step-5-—-after-the-bell" tabindex="-1">Step 5 — After the bell <a class="header-anchor" href="#step-5-—-after-the-bell" aria-label="Permalink to &quot;Step 5 — After the bell&quot;">​</a></h2><p>Once the show is final:</p><ul><li><strong>Results are visible</strong> to players and viewers — summaries update on the show card.</li><li><strong>Fan reactions</strong> land on winners and losers; a decisive win over a popular opponent moves the needle most.</li><li><strong>Rivalries heat up or cool down</strong> based on who fought whom and how.</li><li><strong>Notifications</strong> tell wrestlers and title holders what changed.</li></ul><p>Check the show&#39;s detail page afterwards — it&#39;s also where you review the AI narration and segment results in order.</p><hr><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>The auto-generated <a href="./booker.html">Booker Overview</a> documents every booker screen.</li><li>The <a href="./booker-journey.html">Booker Journey</a> page has video walkthroughs of the full show lifecycle.</li><li>Rivalries, tournaments, and season scheduling are covered in the <a href="./general-manager.html">General Manager</a> guide.</li></ul>`,30)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};